session_start(); require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function okc($n){return defined($n)&&constant($n)!==''&&!str_contains((string)constant($n),'PUT_')&&!str_contains((string)constant($n),'YOUR_');}
function mask($v){$v=(string)$v;return strlen($v)>8?substr($v,0,4).'...'.substr($v,-4):'set';}
function fileok($p){return file_exists($_SERVER['DOCUMENT_ROOT'].$p);}
function tableok($t){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.$t.'?select=id&limit=1');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPGET=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY],CURLOPT_TIMEOUT=>8]);curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return $http>=200&&$http<300;}
$checks=['MARK_EMAIL','MARK_DASHBOARD_PASSWORD','RESEND_API_KEY','RESEND_FROM_EMAIL','SUPABASE_URL','SUPABASE_SERVICE_ROLE_KEY','RETELL_API_KEY','RETELL_AGENT_ID_MARK_PRIORITY','RETELL_FROM_NUMBER','TWILIO_ACCOUNT_SID','TWILIO_AUTH_TOKEN','TWILIO_SMS_FROM','AFTER_HOURS_CRON_KEY'];
$files=['/lead-engine/capture.php','/lead-engine/cron-master.php','/lead-engine/seed-followups.php','/lead-engine/dnc-check.php','/lead-engine/track.php','/lead-engine/conversion-tracker.js','/lead-engine/process-call-outcomes.php','/lead-engine/build-future-sellers.php','/lead-engine/intelligence/import-homeowners-v3.php','/dashboard/operations.php','/dashboard/system-health.php','/dashboard/listing-forecast.php','/dashboard/future-seller-pipeline.php','/dashboard/call-learning.php','/dashboard/homeowner-radar.php','/dashboard/jessica-batch-caller.php','/dashboard/conversions.php','/dashboard/source-roi.php','/dashboard/utm-builder.php','/dashboard/drip-control.php'];
$tables=['leads','homeowner_intelligence','call_intelligence','lead_followup_queue','drip_sequence_templates','mark_action_queue','hot_lead_alerts','conversion_events','cold_call_outcomes','future_seller_pipeline'];
$okChecks=count(array_filter($checks,'okc'));$okFiles=count(array_filter($files,'fileok'));$okTables=0;foreach($tables as $t)if(tableok($t))$okTables++;$cronKey=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'YOUR_KEY';
?>
