<section class="panel"><h2>Files</h2><table><tr><th>File</th><th>Status</th></tr><?php foreach($files as $f):?><tr><td><?=h($f)?></td><td><span class="badge <?=fileok($f)?'ok':'bad'?>"><?=fileok($f)?'Installed':'Missing'?></span></td></tr><?php endforeach;?></table></section>
